from itertools import combinations, product
import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        if mandatory & blocked:
            return {"error": "impossible"}
        options = [job for job in jobs if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in combinations(options, k):
            ids = sorted(job["id"] for job in subset)
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            valid = True
            for job in subset:
                overlaps = sum(other["start"] <= job["start"] < other["end"]
                               for other in subset)
                if overlaps > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "smallest" and ids < best_ids) or
                      (tie == "largest" and ids > best_ids)))):
                best_value, best_ids = value, ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_06():
    def rounded(n, denominator, mode):
        if mode == "floor":
            return n // denominator
        return (2 * n + denominator) // (2 * denominator)

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (sequence, event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000,
                          data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        options = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name]
                              if row["version"] not in blocked.get(name, []) and
                              (name not in pins or row["version"] == pins[name]))
            options.append([None] + versions)

        best_vector = None
        best_install = None
        for values in product(*options):
            chosen = {name: version for name, version in zip(names, values)
                      if version is not None}
            if any(name not in chosen or
                   not bounds[0] <= chosen[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue

            rows = {name: next(row for row in packages[name]
                               if row["version"] == version)
                    for name, version in chosen.items()}
            edges = {}
            valid = True
            for name, row in rows.items():
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    version = chosen.get(target)
                    if version is None or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    deps.append(target)
                if not valid:
                    break
                edges[name] = deps
            if not valid:
                continue

            reached = set()
            active = set()
            cyclic = False

            def visit(name):
                nonlocal cyclic
                if name in active:
                    cyclic = True
                    return
                if name in reached:
                    return
                active.add(name)
                for other in edges.get(name, []):
                    visit(other)
                active.remove(name)
                reached.add(name)

            for name in roots:
                visit(name)
            if cyclic or reached != set(chosen):
                continue
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best_install = vector, chosen

        if best_install is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_install}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit_for.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"],) + start_state]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if (node == data["target"] and mask == full and remaining == 0):
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    choices.append((duration, remaining - 1))
                for duration, next_remaining in choices:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit_for.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival,) + next_state)
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _interval_solver(2, "smallest"),
    "component_02": _interval_solver(1, "largest"),
    "component_03": _interval_solver(2, "largest"),
    "component_04": _interval_solver(1, "smallest"),
    "component_05": _interval_solver(2, "smallest"),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
